<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>پنل ورزشکار | Arash Fitness</title><style>body{margin:0;background:#0b1220;color:#e5e7eb;font:16px Tahoma,Arial,sans-serif}main{max-width:950px;margin:35px auto;padding:20px}h1{color:#6ee7b7}section{background:#182337;padding:22px;border-radius:16px;margin:18px 0}input,textarea,select,button{font:inherit;border-radius:8px;padding:12px;margin:5px 0;box-sizing:border-box}input,textarea,select{width:100%;background:#101827;color:white;border:1px solid #475569}button{border:0;background:#34d399;color:#082f25;font-weight:bold;cursor:pointer}button:disabled{opacity:.5}article{border:1px solid #334155;padding:14px;margin:12px 0;border-radius:10px}small{color:#cbd5e1}.error{color:#fca5a5}#logout{float:left;background:#fda4af}label{display:block;margin-top:10px}.appointment-actions{display:flex;flex-wrap:wrap;gap:6px}.muted{color:#b4c2d4;font-size:13px}#privateMessages{max-height:360px;overflow:auto}.messageCard{border-right:3px solid #34d399}button.secondary{background:#334155;color:#fff}</style><link rel="stylesheet" href="/assets/fitness-portals.css"></head><body><main><h1>پنل اختصاصی ورزشکار</h1><p>برنامه‌های تمرینی و گزارش فعالیت‌های شما</p><nav aria-label="پیوندهای حساب"><a style="color:#a7f3d0" href="/athlete/register">ثبت‌نام ورزشکار جدید</a></nav><p id="message" role="status" aria-live="polite"></p><section id="loginBox"><h2>ورود ورزشکار</h2><form id="login"><label>شماره موبایل یا ایمیل<input name="identifier" type="text" autocomplete="username" inputmode="text" required></label><label>رمز عبور<input name="password" type="password" autocomplete="current-password" required></label><button>ورود</button></form></section><div id="dashboard" hidden><button id="logout">خروج</button><section id="verifyPhoneSection" hidden><h2>تأیید شماره موبایل</h2><p>برای رزرو مشاوره و مشاهده خریدهای قبلی، باید مالکیت شماره <strong id="verifyPhoneNumber"></strong> را تأیید کنید.</p><button type="button" id="sendVerifyPhone">ارسال کد تأیید</button><form id="verifyPhoneForm" hidden><label>کد شش‌رقمی پیامک<input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required></label><button>تأیید شماره</button></form></section><section><h2 id="welcome"></h2><p>برنامه‌های منتشرشده توسط مربی</p><div id="plans"></div></section><section><h2>ثبت فعالیت تمرینی</h2><form id="progressForm"><label>برنامه<select name="training_plan_id" id="planSelect" required></select></label><label>روز تمرینی<select name="session_day" id="daySelect" required></select></label><label>تاریخ<input name="performed_on" type="date" required></label><label>میزان سختی تمرین (۱ تا ۱۰)<input name="effort" type="number" min="1" max="10"></label><label>یادداشت<textarea name="notes" maxlength="2000"></textarea></label><button>ثبت گزارش</button></form></section><section><h2>سوابق تمرین</h2><div id="history"></div></section><section><h2>سفارش‌ها و خریدهای من</h2><p class="muted">تاریخچه خرید با شماره تأییدشده شما نمایش داده می‌شود.</p><div id="athleteOrders"></div><button class="secondary" type="button" id="refreshOrders">بروزرسانی خریدها</button></section>
<section><h2>رزرو جلسه مشاوره با مربی</h2><p class="muted">رزرو جلسه نیازمند شماره موبایل تأییدشده است. زمان‌ها به ساعت دستگاه شما نمایش داده می‌شوند.</p><label>یادداشت اختیاری برای مربی<textarea id="bookingNote" maxlength="500" placeholder="موضوع مشاوره را کوتاه توضیح دهید"></textarea></label><h3>زمان‌های آزاد</h3><div id="availableSlots"></div><h3>جلسات من</h3><div id="myBookings"></div><button class="secondary" type="button" id="refreshSchedule">بروزرسانی زمان‌ها</button></section>
<section><h2>پیام خصوصی به مربی</h2><p class="muted">پیام‌ها فقط برای شما و مربی قابل مشاهده هستند.</p><div id="privateMessages" aria-live="polite"></div><form id="messageForm"><label>متن پیام<textarea id="messageBody" maxlength="2000" required></textarea></label><button>ارسال پیام</button></form><button type="button" id="refreshMessages" class="secondary">بروزرسانی پیام‌ها</button></section>
</div></main><script>
let csrf='',plans=[],athleteId=null;const $=id=>document.getElementById(id);const message=(t,kind='info')=>{$('message').textContent=t;$('message').dataset.kind=kind};
async function api(path,method='GET',body){const res=await fetch('/api/v1/athlete/'+path,{method,credentials:'same-origin',headers:{'Accept':'application/json','Content-Type':'application/json',...(csrf?{'X-CSRF-Token':csrf}:{})},...(body?{body:JSON.stringify(body)}:{})});const json=await res.json().catch(()=>({}));if(!res.ok)throw Error(json.error||json.message||'خطا در ارتباط با سرور');return json}
function el(tag,text){const n=document.createElement(tag);n.textContent=text;return n}
function options(node,items){node.replaceChildren(...items.map(([value,label])=>{let o=document.createElement('option');o.value=value;o.textContent=label;return o}))}
function updateDays(){const p=plans.find(p=>String(p.id)===$('planSelect').value);options($('daySelect'),(p?.sessions||[]).map(s=>[s.day,s.day]))}
async function load(){const me=await api('me');csrf=me.csrfToken;athleteId=me.athlete.id;$('verifyPhoneSection').hidden=!!me.athlete.phone_verified;$('verifyPhoneNumber').textContent=me.athlete.phone||'';$('welcome').textContent='سلام، '+me.athlete.name;$('loginBox').hidden=true;$('dashboard').hidden=false;plans=(await api('plans')).plans;const list=$('plans');list.replaceChildren();for(const p of plans){let a=el('article',p.title+' — '+(p.description||''));for(const s of p.sessions||[]){a.append(el('h3',s.day));for(const ex of s.exercises||[])a.append(el('p',ex.name+' | '+(ex.sets||'-')+' ست | '+(ex.reps||'-')+' تکرار'))}list.append(a)}if(!plans.length)list.append(el('p','هنوز برنامه منتشرشده‌ای ندارید.'));options($('planSelect'),plans.map(p=>[String(p.id),p.title]));updateDays();$('progressForm').querySelector('button').disabled=!plans.length||!$('daySelect').options.length;await history();await Promise.allSettled([loadAppointments(),loadPrivateMessages(),loadOrders()])}
async function history(){const data=await api('progress');$('history').replaceChildren(...data.progress.map(p=>el('article',p.performed_on+' | '+p.session_day+' | سختی: '+(p.effort??'-')+' | '+(p.notes||''))));if(!data.progress.length)$('history').append(el('p','هنوز گزارشی ثبت نشده است.'))}
async function loadOrders(){const host=$('athleteOrders');host.replaceChildren();const d=await api('orders');for(const o of d.orders){const n=el('article',(o.number||o.id)+' · '+o.payment_status+' · '+new Intl.NumberFormat('fa-IR').format(o.amount_toman)+' تومان');for(const item of o.items||[])n.append(el('p',item.title+' × '+item.qty));host.append(n)}if(!d.orders.length)host.append(el('p','هنوز سفارشی با این حساب ثبت نشده است.'))}
$('refreshOrders').onclick=()=>loadOrders().catch(e=>message(e.message,'error'));
function localDate(value){return value?new Date(value).toLocaleString('fa-IR',{dateStyle:'medium',timeStyle:'short'}):'—'}
async function loadAppointments(){const [a,b]=await Promise.all([api('consultations/slots'),api('consultations/bookings')]);const host=$('availableSlots');host.replaceChildren();for(const s of a.slots){const card=el('article',localDate(s.starts_at)+' تا '+localDate(s.ends_at));const btn=el('button','درخواست این زمان');btn.type='button';btn.onclick=async()=>{btn.disabled=true;try{await api('consultations/bookings','POST',{slot_id:s.id,note:$('bookingNote').value.trim()||null});message('درخواست جلسه ثبت شد؛ منتظر تأیید مربی باشید');await loadAppointments()}catch(err){message(err.message,'error')}finally{btn.disabled=false}};card.append(btn);host.append(card)}if(!a.slots.length)host.append(el('p','زمان آزادی برای رزرو وجود ندارد.'));const past=$('myBookings');past.replaceChildren();for(const bkg of b.bookings){const card=el('article',localDate(bkg.starts_at)+' | وضعیت: '+bkg.status);if(bkg.coach_note)card.append(el('p','توضیح مربی: '+bkg.coach_note));if(['requested','confirmed'].includes(bkg.status)){const btn=el('button','لغو جلسه');btn.type='button';btn.className='secondary';btn.onclick=async()=>{btn.disabled=true;try{await api('consultations/bookings/'+bkg.id+'/cancel','POST');message('جلسه لغو شد');await loadAppointments()}catch(err){message(err.message,'error')}finally{btn.disabled=false}};card.append(btn)}past.append(card)}if(!b.bookings.length)past.append(el('p','هنوز جلسه‌ای رزرو نکرده‌اید.'))}
async function loadPrivateMessages(){const data=await api('messages');const host=$('privateMessages');host.replaceChildren();for(const m of data.messages){const card=el('article',(String(m.sender_id)===String(athleteId)?'شما':'مربی')+' | '+localDate(m.created_at));card.className='messageCard';card.append(el('p',m.body));host.append(card)}if(!data.messages.length)host.append(el('p','هنوز پیامی وجود ندارد.'));await api('messages/read','POST')}
$('sendVerifyPhone').onclick=async()=>{try{await api('phone/otp/request','POST',{});$('verifyPhoneForm').hidden=false;message('کد تأیید درخواست شد. لطفاً پیامک خود را بررسی کنید.')}catch(err){message(err.message,'error')}};
$('verifyPhoneForm').onsubmit=async e=>{e.preventDefault();try{await api('phone/verify','POST',{code:e.target.elements.code.value});$('verifyPhoneSection').hidden=true;message('شماره موبایل تأیید شد');await Promise.allSettled([loadAppointments(),loadOrders()])}catch(err){message(err.message,'error')}};
$('refreshSchedule').onclick=()=>loadAppointments().catch(err=>message(err.message,'error'));
$('refreshMessages').onclick=()=>loadPrivateMessages().catch(err=>message(err.message,'error'));
$('messageForm').onsubmit=async e=>{e.preventDefault();try{await api('messages','POST',{body:$('messageBody').value});$('messageBody').value='';await loadPrivateMessages();message('پیام ارسال شد')}catch(err){message(err.message,'error')}};
$('planSelect').addEventListener('change',updateDays);$('login').addEventListener('submit',async e=>{e.preventDefault();try{const f=new FormData(e.target);const r=await fetch('/api/v1/athlete/login',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(Object.fromEntries(f))});if(!r.ok)throw Error('اطلاعات ورود نامعتبر است');await load();message('ورود موفق بود')}catch(err){message(err.message,'error')}});$('progressForm').addEventListener('submit',async e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));d.training_plan_id=Number(d.training_plan_id);d.effort=d.effort?Number(d.effort):null;await api('progress','POST',d);message('گزارش ثبت شد');await history()}catch(err){message(err.message,'error')}});$('logout').onclick=async()=>{try{await api('logout','POST');location.reload()}catch(err){message(err.message,'error')}};load().catch(()=>{$('loginBox').hidden=false;$('dashboard').hidden=true;});
</script></body></html>
